using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Serialize using the typed metadata to prove it works.
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false when metadata
//    isn't available (e.g. for a type the resolver can't handle).
var restricted = new JsonSerializerOptions
{
    // A resolver that only knows about 'int'.
    TypeInfoResolver = new IntOnlyResolver()
};

if (restricted.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata for Person: {info!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for Person — and no exception was thrown.");
}

if (restricted.TryGetTypeInfo(typeof(int), out JsonTypeInfo? intInfo))
{
    Console.WriteLine($"Found metadata for: {intInfo!.Type.Name}");
}

// --- Types ---

record Person(string Name, int Age);

// Minimal resolver that only resolves 'int'.
sealed class IntOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(int))
            return JsonMetadataServices.CreateValueInfo<int>(options, JsonMetadataServices.Int32Converter);

        return null; // signals "I don't know this type"
    }
}

